const [x, y] = [100, 200];
console.log('array:', x, y); // 100 200

const { title, author } = { author: 'Ada', title: 'JS Notes' };
console.log('object:', title, author); // JS Notes Ada

// order in the object literal does not matter
const { author: a2, title: t2 } = { title: 'Same', author: 'Lin' };
console.log('keyed, not positional:', t2, a2); // Same Lin

const { theme = 'light', name: userName = 'guest' } = { theme: undefined, name: 'Sam' };
console.log(theme, userName); // light Sam  (theme default used)

let a = 1, b = 2;
[a, b] = [b, a];
console.log('swapped:', a, b); // 2 1

// default does NOT apply to null
const { count = 5 } = { count: null };
console.log('null stays null:', count); // null

const user = { id: 1, address: { city: 'Pune', zip: '411001' } };
const { address: { city } } = user;
console.log('nested:', city); // Pune

const [first, ...others] = [1, 2, 3, 4];
console.log('rest:', first, others); // 1 [2, 3, 4]

const [, second, , fourth] = ['a', 'b', 'c', 'd'];
console.log('skipping:', second, fourth); // b d

function greet({ name, greeting = 'Hi' } = {}) {
  return `${greeting}, ${name}`;
}
console.log(greet({ name: 'Ada' })); // Hi, Ada

const user = { name: 'Ada', address: { city: 'Pune' } };

function formatUser(u) {
  // TODO: destructure in the parameter instead of using u.name etc.
  const name = u.name;
  const title = u.role || 'member';
  const city = u.address.city;
  return `${name} (${title}) from ${city}`;
}

console.log(formatUser(user)); // Ada (member) from Pune

solution.code:
const user = { name: 'Ada', address: { city: 'Pune' } };

function formatUser({ name, role: title = 'member', address: { city } }) {
  return `${name} (${title}) from ${city}`;
}

console.log(formatUser(user)); // Ada (member) from Pune

